/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Returns the default printer settings for the specified PrintSetupOriginalCopy enumeration value.
/// </summary>
/// <param name = "_printCopyOriginal">PrintSetupOriginalCopy</param>
/// <returns>eturns the default printer settings</returns>
public container getDefaultPrintJobSettings(PrintSetupOriginalCopy _printCopyOriginal)
{
    return new SRSPrintDestinationSettings().pack();        
}

/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// The PrintMgmtDocumentType enumeration value that specifies what document this FormLetterReport 
/// class controls.
/// </summary>
/// <returns>Returns the PrintMgmtDocumentType enumeration value that specifies what document this FormLetterReport class controls.</returns>
public PrintMgmtDocumentType getPrintMgmtDocumentType()
{
    return PrintMgmtDocumentType::METCustActivityStatement;
}

/// <summary>
